"""
DatavionAI Device Platform production installer.

Installs the Device Platform foundation for:
- device registry and lifecycle
- patient/device association
- pairing and connection contracts
- BLE/GATT abstractions
- telemetry ingestion, validation and provenance
- canonical RBAC integration
- Datavion core workflow/event integration
- frontend Device Center + Web Bluetooth foundation
- architecture tests

Safety guarantees:
- never recreates apps/clinical/patients
- never modifies patient_management/family_members
- never creates migrations
- never runs migrate, test, npm or build commands
- validates required project contracts before replacing Device Platform
"""

from __future__ import annotations

